#pragma once
#include <concepts>
#include <cstddef>
#include <span>
#include <string>
#include <string_view>
#include <tuple>
#include <type_traits>
#include <utility>
#include <vector>

#include "connection.hpp"

// Column-tag convention (generated by pg_tablegen):
//   Col::table::name         table name
//   Col::table::key          std::tuple of the primary-key column types
//   Col::table::key_columns  std::array<std::string_view, N> of primary-key column names
//   Col::type, Col::name     column type and name
//   By::table, By::key, By::key_columns   a UNIQUE locator, same shape as the table's key

namespace pg {

template <class Col>
class sql;

namespace detail {

template <class T>
inline constexpr bool is_cell = false;
template <class Col>
inline constexpr bool is_cell<sql<Col>> = true;

inline std::string quote_ident(std::string_view id) {
    std::string out = "\"";
    for (char c : id) {
        if (c == '"') out += '"';
        out += c;
    }
    return out + '"';
}

// `"k1" = $first AND "k2" = $first+1 ...`
inline std::string where_clause(std::span<const std::string_view> cols, std::size_t first) {
    std::string out = " WHERE ";
    for (std::size_t i = 0; i < cols.size(); ++i) {
        if (i) out += " AND ";
        out += quote_ident(cols[i]) + " = $" + std::to_string(first + i);
    }
    return out;
}

// The statements of one cell kind. Key parameters follow the value parameter.
struct cell_sql {
    std::string table, column;     // unquoted names
    std::vector<std::string> key;  // unquoted key column names
    std::string select;  // key...
    std::string set;     // value, key...
    std::string add;     // delta, key...
    std::string sub;     // delta, key...

    cell_sql(std::string_view table_name, std::string_view column_name, std::span<const std::string_view> key_columns)
        : table(table_name), column(column_name), key(key_columns.begin(), key_columns.end()) {
        const std::string t = quote_ident(table), c = quote_ident(column);
        const std::string where_value = where_clause(key_columns, 2);
        select = "SELECT " + c + " FROM " + t + where_clause(key_columns, 1);
        set = "UPDATE " + t + " SET " + c + " = $1" + where_value;
        add = "UPDATE " + t + " SET " + c + " = " + c + " + $1" + where_value;
        sub = "UPDATE " + t + " SET " + c + " = " + c + " - $1" + where_value;
    }
};

// Built once per (column, locator) pair. Never destroyed: cached<Col> writes
// back at process exit and must find the statement text still alive.
template <class Col, class Loc>
const cell_sql& cell_sql_of() {
    static const cell_sql& s = *new cell_sql(Col::table::name, Col::name, std::span<const std::string_view>(Loc::key_columns));
    return s;
}

// A, ... can initialize the elements of the key tuple K, in order. A cell is
// never a key component (it would hijack the copy constructor via its
// conversion operator).
template <class K, class... A>
struct key_args : std::false_type {};
template <class... K, class... A>
    requires(sizeof...(K) == sizeof...(A))
struct key_args<std::tuple<K...>, A...> : std::bool_constant<((std::convertible_to<A, K> && !is_cell<std::remove_cvref_t<A>>) && ...)> {};

template <class K, class... A>
concept key_args_for = key_args<K, A...>::value;

template <class K, class... A, std::size_t... I>
params key_params(std::index_sequence<I...>, A&&... a) {
    params p;
    (p.push_back(to_param<std::tuple_element_t<I, K>>(std::forward<A>(a))), ...);
    return p;
}

}  // namespace detail

// One database cell (table, row, column) used like a variable; every access
// goes to the database.
template <class Col>
class sql {
public:
    using value_type = typename Col::type;

    // Locates the row by primary key.
    template <class... A>
        requires detail::key_args_for<typename Col::table::key, A...>
    explicit sql(A&&... key)
        : stmt_(&detail::cell_sql_of<Col, typename Col::table>()),
          key_(detail::key_params<typename Col::table::key>(std::index_sequence_for<A...>{},
                                                            std::forward<A>(key)...)) {}

    // Locates the row by a unique key.
    template <class By, class... A>
        requires detail::key_args_for<typename By::key, A...>
    sql(By, A&&... key)
        : stmt_(&detail::cell_sql_of<Col, By>()),
          key_(detail::key_params<typename By::key>(std::index_sequence_for<A...>{}, std::forward<A>(key)...)) {}

    sql(const sql&) = default;

    // Assigning one cell to another copies the value, like variables.
    sql& operator=(const sql& other) { return *this = other.get(); }

    value_type get() const {
        conn c;
        auto rows = c.query_params<value_type>(stmt_->select, key_);
        if (rows.empty()) throw not_found(missing());
        return std::move(rows.front());
    }
    operator value_type() const { return get(); }

    sql& operator=(const value_type& v) { return update(stmt_->set, v); }

    sql& operator+=(value_type d)
        requires std::is_arithmetic_v<value_type>
    {
        return update(stmt_->add, d);
    }
    sql& operator-=(value_type d)
        requires std::is_arithmetic_v<value_type>
    {
        return update(stmt_->sub, d);
    }
    sql& operator++()
        requires std::is_arithmetic_v<value_type>
    {
        return *this += value_type(1);
    }
    sql& operator--()
        requires std::is_arithmetic_v<value_type>
    {
        return *this -= value_type(1);
    }

private:
    static std::string missing() {
        return "no row for " + std::string(Col::table::name) + "." + std::string(Col::name);
    }

    // Runs an UPDATE whose first parameter is `v`; zero affected rows is not_found.
    sql& update(const std::string& statement, const value_type& v) {
        detail::params p{detail::to_param(v)};
        p.insert(p.end(), key_.begin(), key_.end());
        conn c;
        if (c.exec_params(statement, p) == 0) throw not_found(missing());
        return *this;
    }

    const detail::cell_sql* stmt_;
    detail::params key_;
};

}  // namespace pg
